import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String str = scanner.next();
        StringBuilder output = new StringBuilder();
        output.append(str.charAt(0));
        boolean replacedAt = false;
        int index = 1;
        while (index < str.length()) {
            if (index + 1 < str.length() && str.charAt(index) == 'a' && str.charAt(index + 1) == 't' && !replacedAt) {
                output.append('@');
                index += 2;
                replacedAt = true;
            } else if (index + 2 < str.length() && str.charAt(index) == 'd' && str.charAt(index + 1) == 'o' && str.charAt(index + 2) == 't') {
                output.append('.');
                index += 3;
            } else {
                output.append(str.charAt(index));
                index++;
            }
        }
        System.out.println(output.toString());
        scanner.close();
    }
}
